head.b:skin:
        /* ===== RESET &amp; BASE ===== */
        *,
        *::before,
        *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
            -webkit-text-size-adjust: 100%;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
            background: #0f172a;
            color: #e2e8f0;
            font-size: 17px;
            line-height: 1.7;
            overflow-x: hidden;
        }

        a {
            color: #38bdf8;
            text-decoration: none;
            transition: color 0.2s ease;
        }

        a:hover {
            color: #7dd3fc;
        }

        img {
            max-width: 100%;
            height: auto;
            display: block;
        }

        ul,
        ol {
            list-style: none;
        }

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
            color: #f8fafc;
            font-weight: 700;
            line-height: 1.25;
        }

        /* ===== UTILITIES ===== */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px;
        }

        .section {
            padding: 80px 0;
        }

        .section-label {
            display: inline-block;
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: #38bdf8;
            margin-bottom: 12px;
        }

        .section-title {
            font-size: clamp(28px, 4vw, 40px);
            margin-bottom: 16px;
        }

        .section-subtitle {
            font-size: 17px;
            color: #94a3b8;
            max-width: 600px;
        }

        .text-gradient {
            background: linear-gradient(135deg, #38bdf8, #a78bfa);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border: 0;
        }

        /* ===== HEADER ===== */
        .site-header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 1000;
            background: rgba(15, 23, 42, 0.85);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border-bottom: 1px solid rgba(51, 65, 85, 0.5);
            transition: background 0.3s ease;
        }

        .header-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 24px;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            text-decoration: none;
        }

        .logo-icon {
            width: 42px;
            height: 42px;
            background: linear-gradient(135deg, #2563eb, #7c3aed);
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 800;
            font-size: 18px;
            color: #fff;
        }

        .logo-text {
            display: flex;
            flex-direction: column;
            line-height: 1.2;
        }

        .logo-name {
            font-size: 18px;
            font-weight: 800;
            color: #f8fafc;
            letter-spacing: -0.3px;
        }

        .logo-name span {
            color: #38bdf8;
        }

        .logo-tagline {
            font-size: 10px;
            font-weight: 600;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            color: #64748b;
        }

        /* Desktop Nav */
        .desktop-nav {
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .desktop-nav a {
            padding: 8px 14px;
            font-size: 14px;
            font-weight: 500;
            color: #94a3b8;
            border-radius: 8px;
            transition: all 0.2s ease;
            white-space: nowrap;
        }

        .desktop-nav a:hover {
            color: #f8fafc;
            background: rgba(56, 189, 248, 0.08);
        }

        .desktop-nav a.active {
            color: #38bdf8;
        }

        /* Header actions */
        .header-actions {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .search-toggle {
            width: 40px;
            height: 40px;
            border: none;
            background: transparent;
            color: #94a3b8;
            border-radius: 10px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease;
        }

        .search-toggle:hover {
            background: rgba(56, 189, 248, 0.1);
            color: #38bdf8;
        }

        .deals-btn {
            padding: 8px 18px;
            font-size: 13px;
            font-weight: 600;
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #7c3aed);
            border: none;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s ease;
            white-space: nowrap;
        }

        .deals-btn:hover {
            transform: translateY(-1px);
            box-shadow: 0 4px 20px rgba(37, 99, 235, 0.4);
        }

        /* Hamburger */
        .mobile-toggle {
            display: none;
            width: 40px;
            height: 40px;
            border: none;
            background: transparent;
            color: #f8fafc;
            cursor: pointer;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 5px;
            border-radius: 8px;
        }

        .mobile-toggle span {
            display: block;
            width: 22px;
            height: 2px;
            background: #f8fafc;
            border-radius: 2px;
            transition: all 0.3s ease;
        }

        .mobile-toggle.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }

        .mobile-toggle.active span:nth-child(2) {
            opacity: 0;
        }

        .mobile-toggle.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -5px);
        }

        /* Mobile menu */
        .mobile-menu {
            display: none;
            position: fixed;
            top: 72px;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(15, 23, 42, 0.98);
            backdrop-filter: blur(20px);
            z-index: 999;
            padding: 24px;
            overflow-y: auto;
        }

        .mobile-menu.active {
            display: block;
        }

        .mobile-menu a {
            display: block;
            padding: 14px 16px;
            font-size: 16px;
            font-weight: 500;
            color: #e2e8f0;
            border-bottom: 1px solid #1e293b;
            transition: all 0.2s ease;
        }

        .mobile-menu a:hover {
            color: #38bdf8;
            padding-left: 24px;
        }

        /* ===== HERO ===== */
        .hero {
            position: relative;
            padding: 160px 0 100px;
            text-align: center;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background:
                radial-gradient(ellipse 60% 50% at 50% 0%, rgba(37, 99, 235, 0.15), transparent),
                radial-gradient(ellipse 40% 40% at 80% 20%, rgba(124, 58, 237, 0.08), transparent);
            pointer-events: none;
        }

        .hero-badge {
            display: inline-block;
            padding: 8px 20px;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: #38bdf8;
            border: 1px solid rgba(56, 189, 248, 0.3);
            border-radius: 50px;
            margin-bottom: 32px;
            background: rgba(56, 189, 248, 0.06);
        }

        .hero h1 {
            font-size: clamp(36px, 6vw, 72px);
            font-weight: 900;
            line-height: 1.1;
            margin-bottom: 24px;
            letter-spacing: -1.5px;
        }

        .hero h1 .accent {
            background: linear-gradient(135deg, #38bdf8, #a78bfa, #38bdf8);
            background-size: 200% auto;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            animation: shimmer 4s ease-in-out infinite;
        }

        @keyframes shimmer {

            0%,
            100% {
                background-position: 0% center;
            }

            50% {
                background-position: 100% center;
            }
        }

        .hero-subtitle {
            font-size: clamp(16px, 2vw, 19px);
            color: #94a3b8;
            max-width: 620px;
            margin: 0 auto 40px;
            line-height: 1.6;
        }

        .hero-ctas {
            display: flex;
            gap: 16px;
            justify-content: center;
            flex-wrap: wrap;
            margin-bottom: 48px;
        }

        .btn-primary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 32px;
            font-size: 15px;
            font-weight: 600;
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            border: none;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-decoration: none;
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 30px rgba(37, 99, 235, 0.4);
            color: #fff;
        }

        .btn-outline {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 32px;
            font-size: 15px;
            font-weight: 600;
            color: #e2e8f0;
            background: transparent;
            border: 1px solid #334155;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.3s ease;
            text-decoration: none;
        }

        .btn-outline:hover {
            border-color: #38bdf8;
            color: #38bdf8;
            background: rgba(56, 189, 248, 0.05);
        }

        .hero-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            justify-content: center;
        }

        .hero-tag {
            padding: 6px 16px;
            font-size: 13px;
            font-weight: 500;
            color: #94a3b8;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 50px;
            transition: all 0.2s ease;
            text-decoration: none;
        }

        .hero-tag:hover {
            color: #38bdf8;
            border-color: rgba(56, 189, 248, 0.4);
            background: rgba(56, 189, 248, 0.08);
        }

        /* ===== AUTHOR BOX ===== */
        .author-box {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            padding: 32px;
            display: flex;
            align-items: center;
            gap: 24px;
            margin: 40px auto;
            max-width: 560px;
            transition: border-color 0.3s ease;
        }

        .author-box:hover {
            border-color: rgba(56, 189, 248, 0.3);
        }

        .author-avatar {
            width: 80px;
            height: 80px;
            border-radius: 50%;
            background: linear-gradient(135deg, #1e293b, #334155);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            font-weight: 800;
            color: #38bdf8;
            flex-shrink: 0;
            border: 2px solid #334155;
        }

        .author-info h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 2px;
        }

        .author-role {
            font-size: 12px;
            font-weight: 700;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            color: #38bdf8;
            margin-bottom: 8px;
        }

        .author-bio {
            font-size: 14px;
            color: #94a3b8;
            line-height: 1.5;
        }

        /* ===== START HERE ===== */
        .start-here {
            background: linear-gradient(180deg, #0f172a, #111d35);
        }

        .steps-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
            margin-top: 48px;
        }

        .step-card {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            padding: 32px;
            position: relative;
            transition: all 0.3s ease;
        }

        .step-card:hover {
            transform: translateY(-4px);
            border-color: rgba(56, 189, 248, 0.3);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
        }

        .step-number {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 48px;
            height: 48px;
            font-size: 20px;
            font-weight: 800;
            color: #38bdf8;
            background: rgba(56, 189, 248, 0.1);
            border-radius: 12px;
            margin-bottom: 20px;
        }

        .step-card h3 {
            font-size: 20px;
            margin-bottom: 12px;
        }

        .step-card p {
            font-size: 15px;
            color: #94a3b8;
            line-height: 1.6;
            margin-bottom: 16px;
        }

        .step-link {
            font-size: 14px;
            font-weight: 600;
            color: #38bdf8;
            display: inline-flex;
            align-items: center;
            gap: 6px;
        }

        .step-link:hover {
            gap: 10px;
        }

        /* ===== CATEGORIES ===== */
        .categories-grid {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 16px;
            margin-top: 48px;
        }

        .category-card {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            padding: 28px 20px;
            text-align: center;
            transition: all 0.3s ease;
            cursor: pointer;
            text-decoration: none;
            display: block;
        }

        .category-card:hover {
            transform: translateY(-4px);
            border-color: rgba(56, 189, 248, 0.3);
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
        }

        .category-icon {
            font-size: 36px;
            margin-bottom: 16px;
        }

        .category-card h3 {
            font-size: 15px;
            font-weight: 600;
            margin-bottom: 6px;
        }

        .category-count {
            font-size: 12px;
            color: #64748b;
            font-weight: 500;
        }

        /* ===== POST CARDS GRID ===== */
        .posts-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
            margin-top: 48px;
        }

        .post-card {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            overflow: hidden;
            transition: all 0.3s ease;
            display: flex;
            flex-direction: column;
        }

        .post-card:hover {
            transform: translateY(-4px);
            border-color: rgba(56, 189, 248, 0.2);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
        }

        .post-thumb {
            width: 100%;
            height: 200px;
            object-fit: cover;
        }

        .post-thumb-placeholder {
            width: 100%;
            height: 200px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 48px;
        }

        .post-thumb-placeholder.t1 {
            background: linear-gradient(135deg, #1e3a5f, #2d1b69);
        }

        .post-thumb-placeholder.t2 {
            background: linear-gradient(135deg, #1a3c34, #1e293b);
        }

        .post-thumb-placeholder.t3 {
            background: linear-gradient(135deg, #2d1b69, #1e293b);
        }

        .post-thumb-placeholder.t4 {
            background: linear-gradient(135deg, #1e293b, #3b1a1a);
        }

        .post-thumb-placeholder.t5 {
            background: linear-gradient(135deg, #1a2d3c, #1e293b);
        }

        .post-thumb-placeholder.t6 {
            background: linear-gradient(135deg, #2a1e3b, #1e293b);
        }

        .post-body {
            padding: 24px;
            flex: 1;
            display: flex;
            flex-direction: column;
        }

        .post-badge {
            display: inline-block;
            padding: 4px 10px;
            font-size: 11px;
            font-weight: 600;
            letter-spacing: 0.5px;
            text-transform: uppercase;
            color: #38bdf8;
            background: rgba(56, 189, 248, 0.1);
            border-radius: 6px;
            margin-bottom: 12px;
            align-self: flex-start;
        }

        .post-card h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 10px;
            line-height: 1.35;
        }

        .post-card h3 a {
            color: #f8fafc;
            transition: color 0.2s ease;
        }

        .post-card h3 a:hover {
            color: #38bdf8;
        }

        .post-excerpt {
            font-size: 14px;
            color: #94a3b8;
            line-height: 1.6;
            margin-bottom: 16px;
            flex: 1;
        }

        .read-more {
            font-size: 14px;
            font-weight: 600;
            color: #38bdf8;
            display: inline-flex;
            align-items: center;
            gap: 6px;
        }

        .read-more:hover {
            gap: 10px;
        }

        /* ===== PRODUCT CARD ===== */
        .product-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 24px;
            margin: 32px 0;
        }

        .card {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            overflow: hidden;
            transition: all 0.3s ease;
            display: flex;
            flex-direction: column;
        }

        .card:hover {
            border-color: rgba(56, 189, 248, 0.3);
            box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
            transform: translateY(-2px);
        }

        .card img {
            width: 100%;
            height: 220px;
            object-fit: contain;
            background: #f8fafc;
            padding: 16px;
        }

        .card .badge {
            display: inline-block;
            margin: 16px 20px 8px;
            padding: 4px 10px;
            font-size: 11px;
            font-weight: 600;
            letter-spacing: 0.5px;
            text-transform: uppercase;
            color: #38bdf8;
            background: rgba(56, 189, 248, 0.1);
            border-radius: 6px;
            align-self: flex-start;
        }

        .card .product-title {
            font-size: 17px;
            font-weight: 700;
            color: #f8fafc;
            padding: 0 20px;
            margin-bottom: 8px;
        }

        .card .description {
            font-size: 14px;
            color: #94a3b8;
            line-height: 1.5;
            padding: 0 20px;
            flex: 1;
        }

        .cta-btn {
            display: block;
            margin: 16px 20px 20px;
            padding: 12px 20px;
            font-size: 14px;
            font-weight: 600;
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            border: none;
            border-radius: 10px;
            text-align: center;
            cursor: pointer;
            transition: all 0.3s ease;
            text-decoration: none;
        }

        .cta-btn:hover {
            transform: translateY(-1px);
            box-shadow: 0 4px 20px rgba(37, 99, 235, 0.4);
            color: #fff;
        }

        /* ===== QUICK VERDICT BOX ===== */
        .quick-verdict {
            background: linear-gradient(135deg, rgba(37, 99, 235, 0.1), rgba(124, 58, 237, 0.05));
            border: 1px solid rgba(56, 189, 248, 0.2);
            border-radius: 16px;
            padding: 28px 32px;
            margin: 32px 0;
        }

        .quick-verdict h3 {
            font-size: 18px;
            color: #38bdf8;
            margin-bottom: 12px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .quick-verdict p {
            font-size: 16px;
            color: #e2e8f0;
            line-height: 1.7;
        }

        /* ===== PROS / CONS BOX ===== */
        .pros-cons {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            margin: 32px 0;
        }

        .pros,
        .cons {
            padding: 24px;
            border-radius: 14px;
            border: 1px solid #334155;
        }

        .pros {
            background: rgba(34, 197, 94, 0.05);
            border-color: rgba(34, 197, 94, 0.2);
        }

        .cons {
            background: rgba(239, 68, 68, 0.05);
            border-color: rgba(239, 68, 68, 0.2);
        }

        .pros h4 {
            color: #22c55e;
            margin-bottom: 12px;
            font-size: 16px;
        }

        .cons h4 {
            color: #ef4444;
            margin-bottom: 12px;
            font-size: 16px;
        }

        .pros li,
        .cons li {
            font-size: 15px;
            color: #e2e8f0;
            padding: 6px 0;
            padding-left: 24px;
            position: relative;
            list-style: none;
        }

        .pros li::before {
            content: '✓';
            position: absolute;
            left: 0;
            color: #22c55e;
            font-weight: 700;
        }

        .cons li::before {
            content: '✗';
            position: absolute;
            left: 0;
            color: #ef4444;
            font-weight: 700;
        }

        /* ===== COMPARISON TABLE ===== */
        .comparison-table {
            width: 100%;
            border-collapse: collapse;
            margin: 32px 0;
            font-size: 15px;
            border-radius: 14px;
            overflow: hidden;
            border: 1px solid #334155;
        }

        .comparison-table thead {
            background: #1e293b;
        }

        .comparison-table th {
            padding: 14px 20px;
            text-align: left;
            color: #38bdf8;
            font-weight: 600;
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .comparison-table td {
            padding: 14px 20px;
            border-bottom: 1px solid #1e293b;
            color: #e2e8f0;
        }

        .comparison-table tr:last-child td {
            border-bottom: none;
        }

        .comparison-table tbody tr {
            background: rgba(15, 23, 42, 0.5);
        }

        .comparison-table tbody tr:hover {
            background: rgba(30, 41, 59, 0.8);
        }

        /* ===== TABLE OF CONTENTS ===== */
        .toc {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 14px;
            padding: 24px 28px;
            margin: 32px 0;
        }

        .toc h3 {
            font-size: 16px;
            margin-bottom: 16px;
            color: #f8fafc;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .toc ol {
            list-style: decimal;
            padding-left: 20px;
        }

        .toc li {
            padding: 6px 0;
            font-size: 15px;
        }

        .toc a {
            color: #94a3b8;
            transition: color 0.2s;
        }

        .toc a:hover {
            color: #38bdf8;
        }

        /* ===== FAQ ACCORDION ===== */
        .faq-section {
            margin: 48px 0;
        }

        .faq-item {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 12px;
            margin-bottom: 12px;
            overflow: hidden;
            transition: border-color 0.3s;
        }

        .faq-item:hover {
            border-color: rgba(56, 189, 248, 0.2);
        }

        .faq-question {
            width: 100%;
            padding: 18px 24px;
            font-size: 16px;
            font-weight: 600;
            color: #f8fafc;
            background: transparent;
            border: none;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: space-between;
            text-align: left;
            font-family: inherit;
        }

        .faq-question::after {
            content: '+';
            font-size: 20px;
            color: #38bdf8;
            transition: transform 0.3s;
            flex-shrink: 0;
            margin-left: 16px;
        }

        .faq-item.active .faq-question::after {
            transform: rotate(45deg);
        }

        .faq-answer {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease;
        }

        .faq-answer-inner {
            padding: 0 24px 18px;
            font-size: 15px;
            color: #94a3b8;
            line-height: 1.7;
        }

        /* ===== DISCLOSURE ===== */
        .disclosure-bar {
            padding: 16px 0;
            text-align: center;
            font-size: 13px;
            color: #64748b;
            border-top: 1px solid #1e293b;
        }

        .disclosure-inline {
            background: rgba(56, 189, 248, 0.06);
            border-left: 3px solid #38bdf8;
            padding: 14px 20px;
            font-size: 13px;
            color: #94a3b8;
            border-radius: 0 8px 8px 0;
            margin: 24px 0;
        }

        /* ===== MEDICAL DISCLAIMER ===== */
        .medical-disclaimer {
            background: rgba(245, 158, 11, 0.06);
            border-left: 3px solid #f59e0b;
            padding: 14px 20px;
            font-size: 13px;
            color: #94a3b8;
            border-radius: 0 8px 8px 0;
            margin: 24px 0;
        }

        /* ===== NEWSLETTER ===== */
        .newsletter {
            background: linear-gradient(135deg, #1e293b, #253449);
            border: 1px solid #334155;
            border-radius: 20px;
            padding: 60px 40px;
            text-align: center;
            max-width: 700px;
            margin: 0 auto;
        }

        .newsletter h2 {
            font-size: 28px;
            margin-bottom: 12px;
        }

        .newsletter p {
            color: #94a3b8;
            margin-bottom: 28px;
        }

        .newsletter-form {
            display: flex;
            gap: 12px;
            max-width: 480px;
            margin: 0 auto;
        }

        .newsletter-form input {
            flex: 1;
            padding: 14px 20px;
            font-size: 15px;
            color: #f8fafc;
            background: #0f172a;
            border: 1px solid #334155;
            border-radius: 10px;
            outline: none;
            font-family: inherit;
            transition: border-color 0.2s;
        }

        .newsletter-form input:focus {
            border-color: #38bdf8;
        }

        .newsletter-form input::placeholder {
            color: #64748b;
        }

        .newsletter-form button {
            padding: 14px 28px;
            font-size: 15px;
            font-weight: 600;
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            border: none;
            border-radius: 10px;
            cursor: pointer;
            transition: all 0.3s;
            font-family: inherit;
            white-space: nowrap;
        }

        .newsletter-form button:hover {
            box-shadow: 0 4px 20px rgba(37, 99, 235, 0.4);
        }

        /* ===== FOOTER ===== */
        .site-footer {
            border-top: 1px solid #1e293b;
            padding: 60px 0 30px;
            margin-top: 80px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 48px;
        }

        .footer-brand .logo {
            margin-bottom: 16px;
        }

        .footer-about {
            font-size: 14px;
            color: #94a3b8;
            line-height: 1.6;
            max-width: 300px;
        }

        .footer-col h4 {
            font-size: 14px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #f8fafc;
            margin-bottom: 16px;
        }

        .footer-col a {
            display: block;
            font-size: 14px;
            color: #94a3b8;
            padding: 5px 0;
            transition: color 0.2s;
        }

        .footer-col a:hover {
            color: #38bdf8;
        }

        .footer-bottom {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding-top: 24px;
            border-top: 1px solid #1e293b;
            font-size: 13px;
            color: #64748b;
        }

        .footer-legal-links {
            display: flex;
            gap: 20px;
        }

        .footer-legal-links a {
            color: #64748b;
            font-size: 13px;
        }

        .footer-legal-links a:hover {
            color: #94a3b8;
        }

        /* ===== STICKY MOBILE CTA ===== */
        .sticky-cta {
            display: none;
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            background: rgba(15, 23, 42, 0.95);
            backdrop-filter: blur(12px);
            border-top: 1px solid #334155;
            padding: 12px 16px;
            z-index: 998;
        }

        .sticky-cta .cta-btn {
            margin: 0;
            text-align: center;
        }

        /* ===== POST / ARTICLE BODY STYLES ===== */
        .article-body h2 {
            font-size: 26px;
            margin: 48px 0 16px;
            padding-top: 16px;
        }

        .article-body h3 {
            font-size: 21px;
            margin: 36px 0 12px;
        }

        .article-body p {
            margin-bottom: 18px;
        }

        .article-body ul,
        .article-body ol {
            padding-left: 24px;
            margin-bottom: 18px;
        }

        .article-body ul {
            list-style: disc;
        }

        .article-body ol {
            list-style: decimal;
        }

        .article-body li {
            padding: 4px 0;
            color: #e2e8f0;
        }

        .article-body blockquote {
            border-left: 3px solid #38bdf8;
            padding: 16px 24px;
            margin: 24px 0;
            background: rgba(56, 189, 248, 0.04);
            border-radius: 0 8px 8px 0;
            color: #94a3b8;
            font-style: italic;
        }

        .article-body strong {
            color: #f8fafc;
        }

        .article-body a {
            border-bottom: 1px solid rgba(56, 189, 248, 0.3);
        }

        .article-body a:hover {
            border-bottom-color: #38bdf8;
        }

        /* ===== RELATED POSTS ===== */
        .related-posts {
            margin: 48px 0;
            padding: 32px;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
        }

        .related-posts h3 {
            font-size: 20px;
            margin-bottom: 20px;
        }

        .related-list a {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px 0;
            border-bottom: 1px solid rgba(51, 65, 85, 0.5);
            color: #e2e8f0;
            font-size: 15px;
            font-weight: 500;
        }

        .related-list a:last-child {
            border-bottom: none;
        }

        .related-list a::before {
            content: '→';
            color: #38bdf8;
            font-size: 14px;
            flex-shrink: 0;
        }

        .related-list a:hover {
            color: #38bdf8;
        }

        /* ===== SEARCH OVERLAY ===== */
        .search-overlay {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(15, 23, 42, 0.95);
            backdrop-filter: blur(20px);
            z-index: 2000;
            align-items: flex-start;
            justify-content: center;
            padding-top: 20vh;
        }

        .search-overlay.active {
            display: flex;
        }

        .search-box {
            width: 90%;
            max-width: 600px;
        }

        .search-input {
            width: 100%;
            padding: 18px 24px;
            font-size: 20px;
            color: #f8fafc;
            background: #1e293b;
            border: 2px solid #334155;
            border-radius: 14px;
            outline: none;
            font-family: inherit;
            transition: border-color 0.2s;
        }

        .search-input:focus {
            border-color: #38bdf8;
        }

        .search-input::placeholder {
            color: #64748b;
        }

        .search-hint {
            text-align: center;
            font-size: 13px;
            color: #64748b;
            margin-top: 12px;
        }

        /* ===== RESPONSIVE ===== */
        @media (max-width: 1024px) {
            .desktop-nav {
                display: none;
            }

            .mobile-toggle {
                display: flex;
            }

            .categories-grid {
                grid-template-columns: repeat(3, 1fr);
            }

            .footer-grid {
                grid-template-columns: 1fr 1fr;
            }
        }

        @media (max-width: 768px) {
            .section {
                padding: 60px 0;
            }

            .steps-grid {
                grid-template-columns: 1fr;
            }

            .categories-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .posts-grid {
                grid-template-columns: 1fr;
            }

            .pros-cons {
                grid-template-columns: 1fr;
            }

            .newsletter {
                padding: 40px 24px;
            }

            .newsletter-form {
                flex-direction: column;
            }

            .footer-grid {
                grid-template-columns: 1fr;
                gap: 32px;
            }

            .footer-bottom {
                flex-direction: column;
                gap: 12px;
                text-align: center;
            }

            .hero {
                padding: 140px 0 80px;
            }

            .hero-ctas {
                flex-direction: column;
                align-items: center;
            }

            .btn-primary,
            .btn-outline {
                width: 100%;
                max-width: 300px;
                justify-content: center;
            }

            .author-box {
                flex-direction: column;
                text-align: center;
            }

            .sticky-cta {
                display: block;
            }

            .deals-btn {
                display: none;
            }

            .product-grid {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 480px) {
            .categories-grid {
                grid-template-columns: 1fr 1fr;
                gap: 10px;
            }

            .category-card {
                padding: 20px 12px;
            }

            body {
                font-size: 16px;
            }
        }

        /* ===== FILTER BUTTONS ===== */
        .filter-btn {
            padding: 10px 22px;
            font-size: 14px;
            font-weight: 600;
            color: #94a3b8;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 50px;
            cursor: pointer;
            transition: all 0.3s ease;
            font-family: inherit;
        }

        .filter-btn:hover {
            color: #f8fafc;
            border-color: rgba(56, 189, 248, 0.4);
            background: rgba(56, 189, 248, 0.08);
        }

        .filter-btn.active {
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #7c3aed);
            border-color: transparent;
        }

        /* ===== CARD NUMBER BADGE ===== */
        .card-number {
            position: absolute;
            top: 12px;
            left: 12px;
            background: linear-gradient(135deg, #2563eb, #7c3aed);
            color: #fff;
            font-size: 12px;
            font-weight: 800;
            padding: 4px 10px;
            border-radius: 8px;
            z-index: 2;
            letter-spacing: 0.5px;
        }

        .card {
            position: relative;
        }

        /* ===== PROGRESS BAR ===== */
        #reading-progress {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            width: 0%;
            background: linear-gradient(90deg, #38bdf8, #818cf8, #c084fc);
            z-index: 9999;
            transition: width 0.1s ease-out;
            box-shadow: 0 0 10px rgba(56, 189, 248, 0.7);
        }

        /* ===== KEYFRAME ANIMATIONS ===== */
        @keyframes pulseGlow {
            0%, 100% { box-shadow: 0 0 15px rgba(56, 189, 248, 0.25); border-color: rgba(56, 189, 248, 0.4); }
            50% { box-shadow: 0 0 30px rgba(124, 58, 237, 0.4); border-color: rgba(167, 139, 250, 0.6); }
        }

        @keyframes badgePulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
        }

        @keyframes floatEffect {
            0%, 100% { transform: translateY(0px); }
            50% { transform: translateY(-6px); }
        }

        @keyframes fadeInScale {
            from { opacity: 0; transform: scale(0.95) translateY(10px); }
            to { opacity: 1; transform: scale(1) translateY(0); }
        }

        .hero-badge {
            animation: pulseGlow 4s infinite ease-in-out;
        }

        /* ===== ENHANCED POST CARDS ===== */
        .post-card {
            cursor: pointer;
            position: relative;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 16px;
            overflow: hidden;
            transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
            display: flex;
            flex-direction: column;
        }

        .post-card:hover {
            transform: translateY(-8px);
            border-color: rgba(56, 189, 248, 0.4);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4), 0 0 20px rgba(56, 189, 248, 0.15);
        }

        .post-thumb-wrap {
            position: relative;
            height: 220px;
            overflow: hidden;
            background: #0f172a;
        }

        .post-thumb-wrap img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .post-card:hover .post-thumb-wrap img {
            transform: scale(1.08);
        }

        .post-meta-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
        }

        .post-read-time {
            font-size: 12px;
            color: #64748b;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .post-badge-hot {
            background: linear-gradient(135deg, #ef4444, #f97316);
            color: #fff;
            font-size: 10px;
            font-weight: 800;
            padding: 3px 8px;
            border-radius: 4px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        /* ===== TOP PICKS CONTROLS ===== */
        .picks-header-bar {
            display: flex;
            flex-wrap: wrap;
            gap: 16px;
            align-items: center;
            justify-content: space-between;
            margin: 32px 0 20px;
            padding-bottom: 16px;
            border-bottom: 1px solid rgba(51, 65, 85, 0.6);
        }

        .filter-group {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }

        .product-search-wrapper {
            position: relative;
            min-width: 260px;
            max-width: 360px;
            flex: 1;
        }

        .product-search-wrapper input {
            width: 100%;
            padding: 11px 16px 11px 40px;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 50px;
            color: #f8fafc;
            font-size: 14px;
            outline: none;
            transition: all 0.25s ease;
        }

        .product-search-wrapper input:focus {
            border-color: #38bdf8;
            box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15);
        }

        .product-search-wrapper svg {
            position: absolute;
            left: 14px;
            top: 50%;
            transform: translateY(-50%);
            color: #64748b;
            pointer-events: none;
        }

        .results-count-badge {
            font-size: 13px;
            color: #94a3b8;
            background: #0f172a;
            border: 1px solid #334155;
            padding: 4px 12px;
            border-radius: 20px;
        }

        /* ===== PRODUCT CARD REFINEMENT ===== */
        .card {
            transition: transform 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
        }

        .card:hover {
            transform: translateY(-6px);
            border-color: rgba(56, 189, 248, 0.4);
            box-shadow: 0 16px 36px rgba(0, 0, 0, 0.4);
        }

        .card img {
            transition: transform 0.3s ease;
        }

        .card:hover img {
            transform: scale(1.03);
        }

        /* ===== AFFILIATE PRODUCT CALLOUT BOX ===== */
        .product-callout {
            background: linear-gradient(135deg, rgba(30, 41, 59, 0.95), rgba(15, 23, 42, 0.95));
            border: 1px solid rgba(56, 189, 248, 0.25);
            border-radius: 18px;
            padding: 28px;
            margin: 32px 0;
            display: flex;
            gap: 28px;
            align-items: center;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
        }

        .product-callout-img-box {
            width: 140px;
            height: 140px;
            background: #fff;
            border-radius: 12px;
            padding: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .product-callout-img-box img {
            max-width: 100%;
            max-height: 100%;
            object-fit: contain;
        }

        .product-callout-content {
            flex: 1;
        }

        .callout-ribbon {
            display: inline-block;
            background: linear-gradient(135deg, #10b981, #059669);
            color: #fff;
            font-size: 11px;
            font-weight: 800;
            letter-spacing: 0.5px;
            text-transform: uppercase;
            padding: 4px 10px;
            border-radius: 6px;
            margin-bottom: 8px;
        }

        .product-callout-title {
            font-size: 19px;
            font-weight: 700;
            color: #f8fafc;
            margin-bottom: 6px;
            line-height: 1.3;
        }

        .product-callout-meta {
            display: flex;
            gap: 16px;
            font-size: 13px;
            color: #38bdf8;
            margin-bottom: 10px;
            font-weight: 600;
        }

        .product-callout-desc {
            font-size: 14px;
            color: #94a3b8;
            line-height: 1.6;
            margin-bottom: 16px;
        }

        .product-callout-cta {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            font-size: 14px;
            font-weight: 700;
            color: #fff;
            background: linear-gradient(135deg, #2563eb, #1d4ed8);
            border-radius: 10px;
            transition: all 0.25s ease;
            text-decoration: none;
        }

        .product-callout-cta:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(37, 99, 235, 0.5);
            color: #fff;
        }

        @media (max-width: 640px) {
            .product-callout {
                flex-direction: column;
                text-align: center;
            }
            .product-callout-img-box {
                margin: 0 auto;
            }
            .product-callout-meta {
                justify-content: center;
            }
        }

        /* ===== ARTICLE MODAL ===== */
        .article-modal {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(15, 23, 42, 0.94);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            z-index: 3000;
            display: none;
            overflow-y: auto;
            padding: 30px 16px 80px;
        }

        .article-modal.active {
            display: flex;
            justify-content: center;
            align-items: flex-start;
        }

        .article-modal-box {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 20px;
            max-width: 900px;
            width: 100%;
            position: relative;
            padding: 44px 48px;
            margin: 20px auto;
            box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.8), 0 0 30px rgba(56, 189, 248, 0.1);
            animation: fadeInScale 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .modal-close-btn {
            position: absolute;
            top: 24px;
            right: 24px;
            width: 44px;
            height: 44px;
            border-radius: 50%;
            background: #0f172a;
            border: 1px solid #334155;
            color: #94a3b8;
            font-size: 24px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease;
            z-index: 10;
        }

        .modal-close-btn:hover {
            color: #f8fafc;
            border-color: #38bdf8;
            transform: rotate(90deg);
        }

        .modal-header-img {
            width: 100%;
            height: 340px;
            object-fit: cover;
            border-radius: 14px;
            margin: 20px 0 28px;
        }

        .modal-byline {
            display: flex;
            align-items: center;
            gap: 16px;
            font-size: 13px;
            color: #94a3b8;
            padding-bottom: 20px;
            margin-bottom: 24px;
            border-bottom: 1px solid #334155;
            flex-wrap: wrap;
        }

        .modal-byline span {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* ===== LIVE SEARCH CONTAINER ===== */
        .search-results-list {
            margin-top: 16px;
            max-height: 50vh;
            overflow-y: auto;
            background: #0f172a;
            border: 1px solid #334155;
            border-radius: 12px;
            padding: 8px;
            display: none;
        }

        .search-results-list.active {
            display: block;
        }

        .search-result-row {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 10px 14px;
            border-radius: 8px;
            color: #e2e8f0;
            text-decoration: none;
            transition: background 0.2s;
            cursor: pointer;
        }

        .search-result-row:hover {
            background: rgba(56, 189, 248, 0.12);
        }

        .search-result-thumb {
            width: 44px;
            height: 44px;
            object-fit: contain;
            background: #fff;
            border-radius: 6px;
            padding: 4px;
            flex-shrink: 0;
        }

        .search-result-title {
            font-size: 14px;
            font-weight: 600;
            color: #f8fafc;
            line-height: 1.3;
        }

        .search-result-meta {
            font-size: 12px;
            color: #38bdf8;
            font-weight: 500;
        }

        /* ===== FLOATING BACK TO TOP ===== */
        .back-to-top {
            position: fixed;
            bottom: 30px;
            right: 30px;
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: rgba(30, 41, 59, 0.95);
            backdrop-filter: blur(10px);
            border: 1px solid #334155;
            color: #38bdf8;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            z-index: 990;
            opacity: 0;
            visibility: hidden;
            transform: scale(0.8);
            transition: all 0.3s ease;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
        }

        .back-to-top.visible {
            opacity: 1;
            visibility: visible;
            transform: scale(1);
        }

        .back-to-top:hover {
            background: #2563eb;
            color: #fff;
            transform: translateY(-4px);
            box-shadow: 0 8px 25px rgba(37, 99, 235, 0.5);
        }

        /* ===== TOAST NOTIFICATION ===== */
        .toast-msg {
            position: fixed;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%) translateY(20px);
            background: #1e293b;
            border: 1px solid #38bdf8;
            color: #f8fafc;
            padding: 12px 24px;
            border-radius: 50px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
            font-size: 14px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 10px;
            z-index: 4000;
            opacity: 0;
            pointer-events: none;
            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .toast-msg.show {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
        }

        /* ===== ZERO STATE ===== */
        .no-products-found {
            grid-column: 1 / -1;
            text-align: center;
            padding: 60px 20px;
            background: #1e293b;
            border: 1px dashed #334155;
            border-radius: 16px;
        }

        .no-products-found h4 {
            font-size: 18px;
            color: #f8fafc;
            margin-bottom: 8px;
        }

        .no-products-found p {
            font-size: 14px;
            color: #94a3b8;
        }


/* ===== BLOGGER SINGLE POST & PAGE INTEGRATION ===== */
.blogger-content-container {
    max-width: 900px;
    margin: 120px auto 60px;
    padding: 0 24px;
}

.blogger-post-header {
    margin-bottom: 32px;
}

.blogger-post-title {
    font-size: clamp(28px, 4.5vw, 42px);
    font-weight: 900;
    line-height: 1.25;
    color: #f8fafc;
    margin-bottom: 16px;
}

.blogger-post-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 16px;
    font-size: 14px;
    color: #94a3b8;
    padding-bottom: 20px;
    border-bottom: 1px solid #334155;
    margin-bottom: 32px;
}

.blogger-post-body {
    font-size: 17px;
    line-height: 1.8;
    color: #cbd5e1;
}

.blogger-post-body p {
    margin-bottom: 24px;
}

.blogger-post-body h2 {
    font-size: 26px;
    color: #f8fafc;
    margin: 40px 0 16px;
    border-bottom: 1px solid #334155;
    padding-bottom: 10px;
}

.blogger-post-body h3 {
    font-size: 20px;
    color: #f8fafc;
    margin: 32px 0 12px;
}

.blogger-post-body ul, .blogger-post-body ol {
    margin: 0 0 24px 24px;
}

.blogger-post-body li {
    margin-bottom: 8px;
}

.blogger-post-body img {
    border-radius: 12px;
    margin: 24px auto;
}

.blogger-post-body blockquote {
    background: #1e293b;
    border-left: 4px solid #38bdf8;
    padding: 18px 24px;
    border-radius: 0 12px 12px 0;
    margin: 28px 0;
    font-style: italic;
    color: #f8fafc;
}

body.script:
//

        // Image CDN & Fallback Engine (Configurable for Blogger / GitHub / Cloudinary)
        window.IMAGE_BASE_URL = window.IMAGE_BASE_URL || 'https://cdn.jsdelivr.net/gh/Bimal-Web/Affilate-marketing-----blogging-site@main/';
        document.addEventListener('DOMContentLoaded', () => {
            if (window.IMAGE_BASE_URL) {
                document.querySelectorAll('img[src^="images/"]').forEach(img => {
                    const originalSrc = img.getAttribute('src');
                    img.src = window.IMAGE_BASE_URL.replace(/\/+$/, '') + '/' + originalSrc;
                });
            }
            // Graceful SVG fallback for any missing image on live blogs
            document.querySelectorAll('.card img, .product-callout-img-box img, .post-thumb-wrap img, .modal-header-img').forEach(img => {
                img.addEventListener('error', function() {
                    if (!this.dataset.hasFallback) {
                        this.dataset.hasFallback = 'true';
                        this.style.objectFit = 'contain';
                        this.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="300" height="220" viewBox="0 0 300 220"><rect width="300" height="220" fill="%231e293b"/><text x="50%25" y="45%25" dominant-baseline="middle" text-anchor="middle" fill="%2338bdf8" font-family="sans-serif" font-size="28" font-weight="bold">💈</text><text x="50%25" y="65%25" dominant-baseline="middle" text-anchor="middle" fill="%2394a3b8" font-family="sans-serif" font-size="12" font-weight="600">HAIRCUTZONEPRO LAB</text></svg>';
                    }
                });
            });
