        // Open Article Modal
        function openArticleModal(articleId) {
            const article = articlesDatabase[articleId];
            if (!article) return;
            const container = document.getElementById('article-modal-content');
            container.innerHTML = `
                <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">
                    <span class="post-badge">${article.category}</span>
                    <span class="results-count-badge">⭐ ${article.rating}</span>
                </div>
                <h1 style="font-size:clamp(24px,4vw,36px);font-weight:900;line-height:1.2;margin-bottom:16px;">${article.title}</h1>
                <div class="modal-byline">
                    <span>✍️ By <strong>${article.author}</strong></span>
                    <span>📅 ${article.date}</span>
                    <span>⏱️ ${article.readTime}</span>
                </div>
                <img src="${article.image}" alt="${article.title}" class="modal-header-img" loading="lazy" />
                <div class="article-body">
                    ${article.content}
                </div>
                <div style="margin-top:36px;padding-top:20px;border-top:1px solid #334155;text-align:center;">
                    <button class="cta-btn" onclick="closeArticleModal()" style="display:inline-block;margin:0 0 12px;padding:12px 32px;">Close Article</button>
                    <p style="font-size:12px;color:#64748b;">HaircutZonePro · Research-backed grooming guides</p>
                </div>
            `;
            const modal = document.getElementById('article-modal');
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
            modal.scrollTop = 0;
        }

        // Close Article Modal
        function closeArticleModal() {
            const modal = document.getElementById('article-modal');
            modal.classList.remove('active');
            document.body.style.overflow = '';
        }

        // Handle Category Filtering from nav or cards
        function handleCategoryFilter(event, category, labelName) {
            if (event) event.preventDefault();
            selectCategoryFilter(category);
            const topPicks = document.getElementById('top-picks');
            if (topPicks) {
                topPicks.scrollIntoView({ behavior: 'smooth' });
            }
            showToast(`Filtered by ${labelName || category}`);
        }

        // Select Category Filter Button
        function selectCategoryFilter(category) {
            const btn = document.querySelector(`.filter-btn[data-filter="${category}"]`);
            if (btn) {
                filterProducts(category, btn);
            } else {
                filterProducts(category);
            }
        }

        // Filter Products
        function filterProducts(category, btn) {
            document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
            if (btn) {
                btn.classList.add('active');
            } else {
                const targetBtn = document.querySelector(`.filter-btn[data-filter="${category}"]`);
                if (targetBtn) targetBtn.classList.add('active');
            }

            let visibleCount = 0;
            const searchInput = document.getElementById('product-quick-filter');
            if (searchInput) searchInput.value = '';

            document.querySelectorAll('#product-grid .card').forEach(card => {
                if (category === 'all' || card.dataset.category === category) {
                    card.style.display = '';
                    visibleCount++;
                    card.style.opacity = '0';
                    card.style.transform = 'translateY(10px)';
                    requestAnimationFrame(() => {
                        card.style.transition = 'opacity 0.35s ease, transform 0.35s ease';
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    });
                } else {
                    card.style.display = 'none';
                }
            });

            const badge = document.getElementById('results-count-badge');
            if (badge) {
                badge.textContent = `Showing ${visibleCount} products`;
            }
        }

        // Quick Search across 100 Products in Top Picks
        function quickSearchProducts(term) {
            const query = term.toLowerCase().trim();
            let visibleCount = 0;
            const activeFilter = document.querySelector('.filter-btn.active')?.dataset.filter || 'all';

            document.querySelectorAll('#product-grid .card').forEach(card => {
                const title = card.querySelector('.product-title')?.textContent.toLowerCase() || '';
                const desc = card.querySelector('.description')?.textContent.toLowerCase() || '';
                const cat = card.dataset.category || '';
                const matchesCategory = (activeFilter === 'all' || cat === activeFilter);
                const matchesQuery = query === '' || title.includes(query) || desc.includes(query);

                if (matchesCategory && matchesQuery) {
                    card.style.display = '';
                    visibleCount++;
                } else {
                    card.style.display = 'none';
                }
            });

            const badge = document.getElementById('results-count-badge');
            if (badge) {
                badge.textContent = `Showing ${visibleCount} products`;
            }
        }

        // Scroll to Top Picks
        function scrollToTopPicks() {
            const topPicks = document.getElementById('top-picks');
            if (topPicks) {
                topPicks.scrollIntoView({ behavior: 'smooth' });
                showToast('🔥 Browsing Top 100 Grooming Picks');
            }
        }

        // Show Toast Notification
        function showToast(message) {
            const toast = document.getElementById('toast-msg');
            if (!toast) return;
            toast.textContent = message;
            toast.classList.add('show');
            clearTimeout(window._toastTimeout);
            window._toastTimeout = setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }

        // Newsletter Submit
        function handleNewsletterSubmit(e) {
            e.preventDefault();
            const btn = document.getElementById('newsletter-submit-btn');
            const emailInput = document.getElementById('newsletter-email');
            const successBox = document.getElementById('newsletter-success');

            btn.textContent = 'Subscribing...';
            btn.disabled = true;

            setTimeout(() => {
                document.getElementById('newsletter-form').style.display = 'none';
                successBox.style.display = 'block';
                showToast('🎉 Successfully subscribed to Grooming Dispatch!');
            }, 800);
        }

        // Mobile Menu helpers
        const mobileToggle = document.getElementById('mobile-toggle');
        const mobileMenu = document.getElementById('mobile-menu');
        function closeMobileMenu() {
            if (mobileToggle) mobileToggle.classList.remove('active');
            if (mobileMenu) mobileMenu.classList.remove('active');
            document.body.style.overflow = '';
        }
        if (mobileToggle && mobileMenu) {
            mobileToggle.addEventListener('click', () => {
                mobileToggle.classList.toggle('active');
                mobileMenu.classList.toggle('active');
                document.body.style.overflow = mobileMenu.classList.contains('active') ? 'hidden' : '';
            });
        }

        // Search Overlay & Live Search Engine
        const searchToggle = document.getElementById('search-toggle');
        const searchOverlay = document.getElementById('search-overlay');
        const searchInput = document.getElementById('search-input');
        const searchResultsList = document.getElementById('search-results-list');

        if (searchToggle && searchOverlay) {
            searchToggle.addEventListener('click', () => {
                searchOverlay.classList.add('active');
                setTimeout(() => searchInput && searchInput.focus(), 100);
            });
            searchOverlay.addEventListener('click', (e) => {
                if (e.target === searchOverlay) searchOverlay.classList.remove('active');
            });
        }

        if (searchInput && searchResultsList) {
            searchInput.addEventListener('input', (e) => {
                const val = e.target.value.toLowerCase().trim();
                if (!val) {
                    searchResultsList.classList.remove('active');
                    searchResultsList.innerHTML = '';
                    return;
                }

                let matchesHtml = '';
                let count = 0;

                // Match articles
                Object.keys(articlesDatabase).forEach(key => {
                    const art = articlesDatabase[key];
                    if (art.title.toLowerCase().includes(val) || art.category.toLowerCase().includes(val)) {
                        count++;
                        matchesHtml += `
                            <div class="search-result-row" onclick="searchOverlay.classList.remove('active'); openArticleModal('${key}');">
                                <img src="${art.image}" class="search-result-thumb" alt="${art.title}" />
                                <div class="search-result-info">
                                    <div class="search-result-title">📖 ${art.title}</div>
                                    <div class="search-result-meta">${art.category} · In-Depth Guide</div>
                                </div>
                            </div>
                        `;
                    }
                });

                // Match products
                document.querySelectorAll('#product-grid .card').forEach(card => {
                    if (count >= 8) return;
                    const title = card.querySelector('.product-title')?.textContent || '';
                    const desc = card.querySelector('.description')?.textContent || '';
                    const img = card.querySelector('img')?.src || '';
                    const num = card.querySelector('.card-number')?.textContent || '';
                    const cat = card.dataset.category || '';

                    if (title.toLowerCase().includes(val) || desc.toLowerCase().includes(val)) {
                        count++;
                        matchesHtml += `
                            <div class="search-result-row" onclick="searchOverlay.classList.remove('active'); document.getElementById('top-picks').scrollIntoView({behavior:'smooth'}); quickSearchProducts('${val}');">
                                <img src="${img}" class="search-result-thumb" alt="${title}" />
                                <div class="search-result-info">
                                    <div class="search-result-title">${num} ${title}</div>
                                    <div class="search-result-meta">🏷️ ${cat.toUpperCase()} · Top 100 Pick</div>
                                </div>
                            </div>
                        `;
                    }
                });

                if (count > 0) {
                    searchResultsList.innerHTML = matchesHtml;
                    searchResultsList.classList.add('active');
                } else {
                    searchResultsList.innerHTML = `<div style="padding:16px;text-align:center;color:#94a3b8;font-size:14px;">No matching articles or products found for "${e.target.value}".</div>`;
                    searchResultsList.classList.add('active');
                }
            });
        }

        // Global ESC key listener
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                if (searchOverlay) searchOverlay.classList.remove('active');
                closeArticleModal();
            }
        });

        // FAQ accordion
        document.querySelectorAll('.faq-question').forEach(btn => {
            btn.addEventListener('click', () => {
                const item = btn.closest('.faq-item');
                const answer = item.querySelector('.faq-answer');
                const isActive = item.classList.contains('active');
                document.querySelectorAll('.faq-item').forEach(i => {
                    i.classList.remove('active');
                    i.querySelector('.faq-answer').style.maxHeight = '0';
                });
                if (!isActive) {
                    item.classList.add('active');
                    answer.style.maxHeight = answer.scrollHeight + 'px';
                }
            });
        });

        // Reading Progress Bar & Header Scroll & Back to Top
        const progressBar = document.getElementById('reading-progress');
        const header = document.getElementById('site-header');
        const backToTopBtn = document.getElementById('back-to-top');

        window.addEventListener('scroll', () => {
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            const docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
            const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;

            if (progressBar) progressBar.style.width = scrollPercent + '%';

            if (header) {
                if (scrollTop > 50) {
                    header.style.background = 'rgba(15, 23, 42, 0.96)';
                } else {
                    header.style.background = 'rgba(15, 23, 42, 0.85)';
                }
            }

            if (backToTopBtn) {
                if (scrollTop > 400) {
                    backToTopBtn.classList.add('visible');
                } else {
                    backToTopBtn.classList.remove('visible');
                }
            }
        }, { passive: true });

    //
